#pragma once

#include <condition_variable>
#include <functional>
#include <list>
#include <mutex>
#include <optional>
#include <thread>

namespace ws {

class ThreadPool {
public:
    using Task = std::function<void()>;

    explicit ThreadPool(std::optional<std::size_t> thread_count = std::nullopt,
                        log::Logger::Ptr logger = log::RootLogger()) noexcept;
    ~ThreadPool() noexcept;

    // コピーとムーブを禁止
    ThreadPool(const ThreadPool&) = delete;
    ThreadPool(ThreadPool&&) = delete;
    ThreadPool& operator=(const ThreadPool&) = delete;
    ThreadPool& operator=(ThreadPool&&) = delete;

    void Start() noexcept;
    void Push(Task task) noexcept;
    void Close() noexcept;

private:
    void ExecProc() noexcept;

    log::Logger::Ptr logger_;
    mutable std::mutex mtx_;
    std::atomic_bool closed_ {true};
    std::size_t thread_count_;
    std::condition_variable cond_;

    std::list<Task> tasks_;
    std::list<std::thread> threads_;
};

}  // namespace ws

#include "thread_pool.h"

namespace ws {

ThreadPool::ThreadPool(std::optional<std::size_t> thread_count, log::Logger::Ptr logger) noexcept
    : logger_(logger), closed_(true), thread_count_(thread_count.value_or(std::thread::hardware_concurrency())) {}

ThreadPool::~ThreadPool() noexcept {
    Close();
}

void ThreadPool::Start() noexcept {
    std::lock_guard<std::mutex> lock(mtx_);
    if (!closed_) return;
    closed_ = false;
    for (std::size_t i = 0; i < thread_count_; ++i) {
        threads_.emplace_back([this]() { ExecProc(); });
    }
}

void ThreadPool::Push(Task task) noexcept {
    std::lock_guard<std::mutex> lock(mtx_);
    if (closed_) return;
    tasks_.push_back(std::move(task));
    cond_.notify_one();
}

void ThreadPool::Close() noexcept {
    std::lock_guard<std::mutex> lock(mtx_);
    if (closed_) return;
    closed_ = true;
    cond_.notify_all();
    for (auto& thread : threads_) {
        if (thread.joinable()) thread.join();
    }
    threads_.clear();
}

void ThreadPool::ExecProc() noexcept {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx_);
        cond_.wait(lock, [this]() { return !tasks_.empty() || closed_; });
        if (closed_ && tasks_.empty()) break;
        Task task = std::move(tasks_.front());
        tasks_.pop_front();
        lock.unlock();
        try {
            task();
        } catch (...) {
            if (logger_) logger_->Error("Task execution failed");
        }
    }
}

}  // namespace ws
